UPDATE sach SET mo_ta = 'Gợi mở sự đa dạng của động vật qua môi trường sống, cách kiếm ăn và những đặc điểm thích nghi dễ quan sát. Nội dung giúp người đọc chú ý hơn đến vai trò của các loài trong tự nhiên và ý nghĩa của việc bảo vệ môi trường sống. Phù hợp cho hoạt động đọc khám phá và trò chuyện cùng trẻ về thế giới sinh vật.' WHERE ma_sach = 'S026' AND ten_sach = 'Thế giới động vật quanh ta' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
UPDATE sach SET mo_ta = 'Kết nối những khái niệm vật lý cơ bản với các hiện tượng quen thuộc như chuyển động, âm thanh, ánh sáng và nhiệt. Nội dung khuyến khích người đọc quan sát, đặt giả thuyết và tìm cách giải thích thay vì chỉ ghi nhớ công thức. Phù hợp để tạo hứng thú học tập và liên hệ kiến thức trên lớp với đời sống.' WHERE ma_sach = 'S027' AND ten_sach = 'Vật lý trong cuộc sống' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
