UPDATE sach SET mo_ta = 'Giới thiệu những nét cơ bản về vị trí, địa hình, khí hậu và các vùng lãnh thổ Việt Nam. Nội dung giúp người học liên hệ điều kiện tự nhiên với sinh hoạt, sản xuất và sự đa dạng giữa các địa phương. Phù hợp để củng cố kiến thức nền trước khi tìm hiểu sâu hơn về từng vùng.' WHERE ma_sach = 'S030' AND ten_sach = 'Địa lý Việt Nam nhập môn' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
