UPDATE sach SET mo_ta = 'Giới thiệu cách đọc ký hiệu, phương hướng và tỷ lệ để hiểu những thông tin cơ bản trên bản đồ. Các tình huống tìm đường và lập hành trình giúp người đọc kết nối kiến thức địa lý với việc khám phá không gian. Phù hợp với người mới làm quen bản đồ hoặc muốn rèn khả năng quan sát và định hướng.' WHERE ma_sach = 'S032' AND ten_sach = 'Bản đồ và hành trình khám phá' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
