UPDATE sach SET mo_ta = 'Giới thiệu cách mô tả dữ liệu, nhận biết biến cố và suy nghĩ về mức độ không chắc chắn trong các tình huống đơn giản. Người học có thể làm quen với số đo tổng hợp, biểu đồ và những lập luận thống kê ban đầu. Phù hợp với sinh viên cần nền tảng để đọc hiểu dữ liệu và tiếp cận các môn học có sử dụng thống kê.' WHERE ma_sach = 'S034' AND ten_sach = 'Nhập môn xác suất thống kê' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
