UPDATE sach SET mo_ta = 'Gợi mở cách quan sát thành phần bữa ăn, lựa chọn thực phẩm đa dạng và xây dựng thói quen ăn uống phù hợp với sinh hoạt. Nội dung giúp người đọc quan tâm hơn đến việc chuẩn bị và cân đối bữa ăn trong gia đình. Đây là nội dung tham khảo phổ thông; nhu cầu dinh dưỡng riêng cần được trao đổi với người có chuyên môn.' WHERE ma_sach = 'S037' AND ten_sach = 'Dinh dưỡng trong bữa ăn hằng ngày' AND (mo_ta = 'Dữ liệu học tập; tên sách, tác giả, giá và liên kết NXB chỉ để minh họa' OR mo_ta IS NULL OR TRIM(mo_ta) = '');
